#!/usr/bin/env node
// Regenerates question-art.js from the files in assets/questions/q/.
// Usage: node tools/question-art-manifest.js
const fs = require('fs'); const path = require('path');
const ROOT = path.join(__dirname, '..');
const dir = path.join(ROOT, 'assets/questions/q');
const ids = fs.readdirSync(dir).filter(f => f.endsWith('.jpg')).map(f => f.slice(0, -4)).sort();
const out = `(()=>{
  const K=window.KWIZILLO_M1=window.KWIZILLO_M1||{};
  // Generated by tools/question-art-manifest.js from assets/questions/q/. One
  // 16:9 illustration per question id, shared by the Dutch and English banks.
  // Never edit by hand; rerun the tool after adding or removing images.
  K.QUESTION_ART_DIR='assets/questions/q/';
  K.QUESTION_ART_IDS=new Set(${JSON.stringify(ids)});
  K.questionArtFor=id=>K.QUESTION_ART_IDS.has(id)?K.QUESTION_ART_DIR+id+'.jpg':null;
})();
`;
fs.writeFileSync(path.join(ROOT, 'question-art.js'), out);
console.log(`question-art.js: ${ids.length} illustrations`);
